public static HumanMadeObject Statement_With_Creation_And_License()
{
    var nightwatch = new HumanMadeObject()
        .WithContext()
        .WithId("https://linked.art/example/object/nightwatch/70")
        .WithLabel("Night Watch");

    nightwatch.ReferredToBy = [
        new LinguisticObject()
            .WithClassifiedAs(Aat.Description, Aat.Statement)
            .WithClassifiedAs(Aat.Term("300456841"))
            .WithContent("Rembrandt's The Night Watch is a dynamic 17th-century group portrait of an Amsterdam militia company ...")
            .WithCreatedBy(c => c
                .WithTechnique(Aat.Term("300456842"))
                .WithTimeSpan(new LinkedArtTimeSpan
                {
                    BeginOfTheBegin = new LinkedArtDate(2024, 11, 7, 20, 50, 0),
                    EndOfTheEnd = new LinkedArtDate(2024, 11, 7, 20, 50, 0)
                }))
            .WithSubjectTo(
                new Right()
                    .WithClassifiedAs("https://creativecommons.org/licenses/by/4.0/", "CC-BY")
                    .WithName("CC-BY 4.0"))
    ];

    return nightwatch;
}

public static HumanMadeObject Two_Accession_Numbers()
{
    var portrait = new HumanMadeObject()
        .WithContext()
        .WithId("https://linked.art/example/object/yiadom-boakye/1")
        .WithLabel("Portrait of Lynette Yiadom-Boakye")
        .WithClassifiedAs(Aat.Painting, Aat.TypeOfWork);

    var yuagId = new Identifier("2021.25.1").AsAccessionNumber();
    yuagId.AssignedBy = [
        new AttributeAssignment()
        {
            CarriedOutBy = [
                new Group()
                    .WithId("https://linked.art/example/group/yuag")
                    .WithLabel("Yale University Art Gallery")
                    .WithClassifiedAs(Aat.Museum)
            ]
        }
    ];

    var ycbaId = new Identifier("B2021.5").AsAccessionNumber();
    ycbaId.AssignedBy = [
        new AttributeAssignment()
        {
            CarriedOutBy = [
                new Group()
                    .WithId("https://linked.art/example/group/ycba")
                    .WithLabel("Yale Center for British Art")
                    .WithClassifiedAs(Aat.Museum)
            ]
        }
    ];
    portrait.IdentifiedBy = [ yuagId, ycbaId ];

    return portrait;
}

